policies:
@rule_id("base_permit")
permit (principal, action, resource);
@tier("soft") @rule_id("force_push_any") @approval_timeout_s("300") @severity("medium") @category("destructive")
forbid (principal, action == Agent::Action::"execute_bash", resource) when { context.command like "*git push --force*" || context.command like "*git push -f *" || context.command like "*git push -f" || context.command like "*git push * --force*" || context.command like "*git push * -f" || context.command like "*git push * -f\n*" || context.command like "*git push * -f;*" || context.command like "*git push * -f ;*" || context.command like "*git push * -f&*" || context.command like "*git push * -f &*" || context.command like "*git push * -f|*" || context.command like "*git push * -f |*" || context.command like "*git push * -f>*" || context.command like "*git push * -f >*" || context.command like "*git push * -f 2>*" };
